package org.brightstats.desktop;
import java.util.*;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.layout.*;import org.brightstats.stats.SemSensitivity;
final class SensitivityPlots {
 private SensitivityPlots(){}
 static void influence(TabPane tabs,SemSensitivity.Influence fit){NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setLabel("Tested deletion index");x.setForceZeroInRange(false);y.setLabel("Generalized Cook distance");ScatterChart<Number,Number> chart=new ScatterChart<>(x,y);chart.setAnimated(false);chart.setLegendVisible(false);chart.setTitle("Exact deletion influence");chart.setPrefHeight(440);var series=new XYChart.Series<Number,Number>();series.setName("Usable deletion refits");Label selected=new Label("Select a point to inspect its unit and original source rows.");selected.setWrapText(true);selected.setMinHeight(Region.USE_PREF_SIZE);for(int i=0;i<fit.deletions().size();i++){var deletion=fit.deletions().get(i);if(!deletion.usable()||deletion.generalizedCookDistance()==null||!Double.isFinite(deletion.generalizedCookDistance()))continue;var point=new XYChart.Data<Number,Number>(i+1,deletion.generalizedCookDistance(),org.brightstats.report.GraphicPoint.original("Unit "+deletion.unit(),deletion.removedSourceRows(),List.of()));series.getData().add(point);point.nodeProperty().addListener((o,a,node)->{if(node!=null){String text="Unit "+deletion.unit()+"\nOriginal rows: "+deletion.removedSourceRows()+"\nCook distance: "+deletion.generalizedCookDistance()+"\nLikelihood displacement: "+deletion.likelihoodDisplacement();Tooltip.install(node,new Tooltip(text));node.setOnMouseClicked(e->selected.setText(text));if(!node.accessibleHelpProperty().isBound())node.setAccessibleHelp(text);}});}chart.getData().add(series);Label note=new Label("Only usable refits have plotted distances; failed attempts remain in the accounting table. This is descriptive sensitivity, with no automatic outlier threshold or row deletion. Click a point for source-row identity.");note.setWrapText(true);note.setMinHeight(Region.USE_PREF_SIZE);VBox panel=new VBox(10,note,selected,chart);panel.setStyle("-fx-padding:12;");VBox.setVgrow(chart,Priority.ALWAYS);Tab tab=new Tab("Deletion influence plot",panel);tab.setClosable(false);tabs.getTabs().add(tab);}
 static void multiverse(TabPane tabs,SemSensitivity.Multiverse fit){ComboBox<SemSensitivity.ParameterRange> parameter=new ComboBox<>();parameter.getItems().setAll(fit.comparableParameterRanges());parameter.setConverter(new javafx.util.StringConverter<>(){public String toString(SemSensitivity.ParameterRange value){return value==null?"":value.parameter()+" — "+value.locationSignature();}public SemSensitivity.ParameterRange fromString(String value){return null;}});parameter.setAccessibleText("Comparable parameter and location signature");parameter.setMaxWidth(Double.MAX_VALUE);NumberAxis x=new NumberAxis();x.setForceZeroInRange(false);x.setLabel("Estimate and within-specification pointwise interval");CategoryAxis y=new CategoryAxis();y.setLabel("Prespecified alternative");y.setAutoRanging(false);LineChart<Number,String> chart=new LineChart<>(x,y);chart.setAnimated(false);chart.setLegendVisible(false);chart.setCreateSymbols(true);chart.setTitle("Specification sensitivity");chart.setPrefHeight(440);Runnable refresh=()->{chart.getData().clear();var target=parameter.getValue();if(target==null)return;y.getCategories().setAll(fit.alternatives().stream().map(SemSensitivity.Alternative::name).toList());for(var alternative:fit.alternatives()){if(!alternative.regular())continue;var model=alternative.fit().model();for(int j=0;j<model.parameters().size();j++){var term=model.parameters().get(j);if(!term.name().equals(target.parameter())||!SemSensitivity.parameterSignature(model,term).equals(target.locationSignature()))continue;var estimate=alternative.fit().terms().get(j);var series=new XYChart.Series<Number,String>();series.setName(alternative.name());if(Double.isFinite(estimate.lower()))series.getData().add(new XYChart.Data<>(estimate.lower(),alternative.name()));series.getData().add(new XYChart.Data<>(estimate.estimate(),alternative.name()));if(Double.isFinite(estimate.upper()))series.getData().add(new XYChart.Data<>(estimate.upper(),alternative.name()));chart.getData().add(series);}}};parameter.valueProperty().addListener((o,a,b)->refresh.run());parameter.getSelectionModel().selectFirst();Label note=new Label("Intervals belong to each fitted specification and are not adjusted or pooled across exploration. Empty alternative rows denote failed fits, absent parameters or a different modeled location. Shared labels alone do not establish the same scientific estimand.");note.setWrapText(true);note.setMinHeight(Region.USE_PREF_SIZE);VBox panel=new VBox(10,note,parameter,chart);panel.setStyle("-fx-padding:12;");VBox.setVgrow(chart,Priority.ALWAYS);Tab tab=new Tab("Specification coefficient plot",panel);tab.setClosable(false);tabs.getTabs().add(tab);}
}
